data class FeedState(val loading:Boolean=false,val items:List<PostUi> = emptyList(),val error:String?=null)
sealed interface FeedMutation { data object Loading:FeedMutation; data class Data(val items:List<PostUi>):FeedMutation; data class Failed(val message:String):FeedMutation }
fun reduce(s:FeedState,m:FeedMutation)=when(m){
 FeedMutation.Loading -> s.copy(loading=true,error=null)
 is FeedMutation.Data -> s.copy(loading=false,items=m.items)
 is FeedMutation.Failed -> s.copy(loading=false,error=m.message)
}

class FeedViewModel(private val repo:FeedRepository):ViewModel(){
 private val actions=MutableSharedFlow<FeedAction>(extraBufferCapacity=32)
 private val _state=MutableStateFlow(FeedState())
 val state:StateFlow<FeedState> = _state
 fun onAction(a:FeedAction){ actions.tryEmit(a) }
 init { viewModelScope.launch { actions.collectLatest { a -> when(a){
   FeedAction.Refresh -> runCatching { repo.refresh() }
     .onStart { _state.update { reduce(it,FeedMutation.Loading) } }
     .onSuccess { x -> _state.update { reduce(it,FeedMutation.Data(x)) } }
     .onFailure { e -> _state.update { reduce(it,FeedMutation.Failed(e.userMessage())) } }
 } } } }
}
